_DATA = json.loads(zlib.decompress(base64.b85decode(_PAYLOAD)).decode())
OUTPUTS = {ROOT / path: content for path, content in _DATA.items()}

def main():
    for path, content in OUTPUTS.items():
        path.parent.mkdir(parents=True, exist_ok=True)
        path.write_text(content)

if __name__ == "__main__":
    main()
